import{_ as a}from"./chunks/live.DqM0EmIK.js";import{_ as i,o as l,c as r,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const f=JSON.parse('{"title":"Live: живая карта","description":"","frontmatter":{"pageId":"players/live","contentRevision":7},"headers":[],"relativePath":"ru/players/live.md","filePath":"ru/players/live.md"}'),o={name:"ru/players/live.md"};function s(n,e,p,h,d,c){return l(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="live-живая-карта" tabindex="-1">Live: живая карта <a class="header-anchor" href="#live-живая-карта" aria-label="Permalink to &quot;Live: живая карта&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><img class="wiki-art" src="'+a+'" alt="Владелец симулирует карту; гость передаёт приказы и получает обновления." width="960" height="440"><p class="wiki-caption">Владелец симулирует карту; гость передаёт приказы и получает обновления.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Гость предлагает live-рейд или live-визит с выбранными пешками. Хозяин принимает приглашение (по умолчанию 60 секунд на ответ). После загрузки гость видит зеркало карты; команды исполняются у хозяина, который остаётся авторитетом симуляции и сейва.</p><p>Скорость согласуется по более медленному запросу. Гость использует собственный бюджет пауз (по умолчанию 10 по 60 секунд). Пауза на письмах учитывает более строгую настройку участников. Для окончания гость выходит, хозяин может прервать сессию.</p><p>При потере связи дождись PeerBack/переподключения. Повторы продолжаются каждые 60 секунд; после двух минут предлагается выход в меню. Рассинхронизация требует нового снимка, а не ручной правки карты.</p><h2 id="live-flow" tabindex="-1">Совместная сессия: действия гостя и хозяина <a class="header-anchor" href="#live-flow" aria-label="Permalink to &quot;Совместная сессия: действия гостя и хозяина {#live-flow}&quot;">​</a></h2><ol><li>Гость отправляет live-рейд/визит караваном или капсулами. Хозяин должен быть онлайн дома.</li><li>Хозяин отвечает на приглашение за минуту. При отказе/таймауте рейд продолжится обычным выбранным режимом; пешки live-визита вернутся почтой.</li><li>Игра гостя сохраняет дом и загружает зеркало. Хозяин ждёт готовности зеркала с паузой.</li><li>Гость выделяет <strong>свои</strong> пешки, отдаёт приказы, меняет работу/расписание. Всё исполняется у хозяина; остальные объекты доступны для просмотра.</li><li>В верхнем правом оверлее следите за состоянием, tick и паузами. Действует меньшая из выбранных скоростей; H/G показывают пожелания сторон.</li><li>Гость выбирает «End session», хозяин — «Abort session». Вернувшиеся пешки и допустимая добыча приходят по серверному результату, не путём копирования зеркального сейва.</li></ol><p>Работник аванпоста на карте хозяина во время визита остаётся зеркалом пешки гостя. Защищённый возврат использует исходный UUID работника и серверную квитанцию.</p><p>Домашнее сохранение перед загрузкой зеркала содержит реестр UUID и защитные квитанции, даже когда live-сессия уже началась. Если этот реестр неоднозначен, загрузка зеркала останавливается до записи домашнего сохранения.</p><p>Когда все гостевые пешки мертвы, пленены или ушли, хозяин завершает сессию. Живая, но лежащая/переносимая пешка всё ещё может удерживать её активной.</p><h2 id="live-failure" tabindex="-1">Паузы, отставание зеркала и разрыв <a class="header-anchor" href="#live-failure" aria-label="Permalink to &quot;Паузы, отставание зеркала и разрыв {#live-failure}&quot;">​</a></h2><p>Бюджет гостя по умолчанию — десять пауз до минуты. Хозяин не расходует этот бюджет. Пауза по письму берёт более строгое из настроек сторон (Never / Major / Any threat), не расходует гостевой лимит и снимается выбором скорости. Это заменяет ванильную авто-паузу на время сессии.</p><p>Если зеркало отстало, запрашивается новый снимок; не пытайся «свести» карты ручным редактированием. При потере стороны другой участник ждёт несколько минут. После истечения ожидания потерянный рейдер передаётся AI хозяина; при потере хозяина завершение будет сообщено его игрой после следующего входа. Это может отложить возврат, поэтому не создавай пешек вручную.</p><p>Coop использует похожее зеркало, но назначенные пешки принадлежат хозяину и никогда не являются гостевой почтовой поставкой.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Хозяин должен оставаться онлайн. Live не создаёт самостоятельную вторую версию сейва. Не завершай сессию удалением журналов или принудительной выдачей пешек.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./coop">Постоянная совместная колония</a></li><li><a href="./raids-incidents">Рейды и платные события</a></li><li><a href="./troubleshooting">Проблемы игрока</a></li></ul>',21)])])}const m=i(o,[["render",s]]);export{f as __pageData,m as default};
